import os # Reproduce final saved checkpoints in a genuinely fresh Python process.
os.environ['OMP_NUM_THREADS']='1';os.environ['OPENBLAS_NUM_THREADS']='1' # Use the same deterministic CPU arithmetic configuration.
import argparse,copy,json # Preserve explicit output architecture and independent future-label poisoning checks.
from pathlib import Path # Resolve canonical model and native-reference provenance.
import numpy as np # Compare complete full-field predictions without spatial sampling.
import torch # Read the checkpoint's declared output semantics and dimensions.
import complex_operator as base # Reuse only the actual frozen full-field inference interface.
from complex_operator_finalize import load # Dispatch explicitly between direct-state and incremental-state checkpoints.
def run(family): # Replay each completed model version after the original final evaluation process has exited.
    registry=json.loads((base.ROOT/'learning/campaign_learning_index.json').read_text());directory=base.ROOT/registry['families'][family];contract=json.loads((directory/'experiment_contract.json').read_text());source=directory/'source_index.json';source=source if source.exists() else base.resolve_path(contract['source_index']);index=json.loads(source.read_text());row=next(row for row in index['cases'] if row['split']=='test');case=base.read_case(row);frozen=json.loads((directory/'frozen_models_before_test.json').read_text());checks=[] # Select one actual independent test history only after its canonical final outputs exist.
    for strategy,receipt in frozen.items(): # Verify all three saved prediction policies in this new interpreter.
        checkpoint_path=base.resolve_path(receipt['checkpoint']);checkpoint=torch.load(checkpoint_path,map_location='cpu',weights_only=False);assert base.digest(checkpoint_path)==receipt['sha256'];model,norm=load(checkpoint_path);prediction=base.rollout(model,case,norm);saved=np.load(directory/'final_test'/strategy/f"{case['id']}.npz",allow_pickle=False)['prediction'];scale=np.asarray(norm['state_scale'])[None,None,:];difference=float(np.max(np.abs(prediction-saved)/scale));poisoned=copy.deepcopy(case);poisoned['states'][1:]=1234567.;poisoned['reference'][1:]=-7654321.;poison_prediction=base.rollout(model,poisoned,norm);poison_difference=float(np.max(np.abs(prediction-poison_prediction)/scale)) # Poison every available future-truth array while preserving only the known initial state and independently prescribed inputs.
        checks.append({'strategy':strategy,'case':case['id'],'checkpoint_sha256':receipt['sha256'],'architecture_variant':checkpoint.get('architecture_variant','incremental_normalized_state'),'actual_reconstructed_class':type(model).__name__,'width':checkpoint['width'],'depth':checkpoint['depth'],'fresh_process_saved_prediction_max_normalized_difference':difference,'both_future_truth_arrays_poisoned_difference':poison_difference,'passed':difference==0. and poison_difference==0.}) # Catch a checkpoint that loads matching tensor names but applies the wrong output recurrence.
    result={'family':family,'fresh_process':True,'checks':checks,'passed':all(item['passed'] for item in checks),'future_native_states_used_for_prediction':False};base.write(directory/'fresh_process_replay.json',result);print(json.dumps(result,ensure_ascii=False),flush=True) # Return exact replay evidence without claiming independent engineering accuracy.
if __name__=='__main__': # Launch this verification separately from training and final evaluation.
    parser=argparse.ArgumentParser();parser.add_argument('--family',choices=['friction','rebar','thermoplastic'],required=True);run(parser.parse_args().family) # Require an already finalized canonical physical family.
